vector<WeatherData> readWeatherData(string filename) {
    vector<WeatherData> data;
    ifstream file(filename);
    string line;
    while (getline(file, line)) {
        stringstream ss(line);
        double temperature, humidity, cloudCover, precipitation;
        int season, label;
        ss >> temperature >> humidity >> cloudCover >> precipitation >> season >> label;
        data.push_back({temperature, humidity, cloudCover, precipitation, season, label});
