    shuffle(data.begin(), data.end(), gen);
    int splitIndex = data.size() * splitRatio;
    for (int i = 0; i < splitIndex; i++) {
        trainData.push_back(data[i]);
    }
    for (int i = splitIndex; i < data.size(); i++) {
        testData.push_back(data[i]);
    }
    return {trainData, testData};
}
int predict(vector<WeatherData>& trainData, vector<WeatherData>& testData) {
    int numTrees = 100;
    int numFeatures = 3;
    int numClasses = 2;
    vector<vector<int>> treePredictions(numTrees, vector<int>(testData.size()));
    for (int i = 0; i < numTrees; i++) {
        vector<WeatherData> bootstrapData;
        for (int j = 0; j < trainData.size(); j++) {
            int index = rand() % trainData.size();
            bootstrapData.push_back(trainData[index]);
        }
        for (int j = 0; j < testData.size(); j++) {
            vector<double> features(numFeatures);
            features[0] = bootstrapData[j].temperature;
            features[1] = bootstrapData[j].humidity;
            features[2] = bootstrapData[j].cloudCover;
            int label = bootstrapData[j].label;
            int season = bootstrapData[j].season;
            if (season == 1) {
                features[0] += 10;
            } else if (season == 2) {
                features[0] -= 10;
            }
            int featureIndex = rand() % numFeatures;
            if (featureIndex == 0) {
                if (features[0] < 20) {
                    treePredictions[i][j] = 0;
                } else {
                    treePredictions[i][j] = 1;
                }
            } else if (featureIndex == 1) {
                if (features[1] < 50) {
                    treePredictions[i][j] = 0;
                } else {
                    treePredictions[i][j] = 1;
                }
            } else {
                if (features[2] < 50) {
                    treePredictions[i][j] = 0;
                } else {
                    treePredictions[i][j] = 1;
                }
            }
        }
    }
    vector<int> finalPredictions(testData.size());
    for (int i = 0; i < testData.size(); i++) {
        int numZeros = 0, numOnes = 0;
        for (int j = 0; j < numTrees; j++) {
            if (treePredictions[j][i] == 0) {
                numZeros++;
