Certainly! Here is a Scala code that implements the Apriori algorithm with the specified options:
```scala
import scala.collection.mutable.ListBuffer
class Apriori(val transactions: List[List[String]], val minSupport: Double, val minConfidence: Double, val maxItemsetSize: Int) {
  private var itemsets: List[List[String]] = List()
  private var frequentItemsets: List[List[String]] = List()
  private var associationRules: List[(List[String], List[String])] = List()
  def run(): Unit = {
    generateItemsetsOfSizeOne()
    var k = 2
    while (itemsets.nonEmpty && k <= maxItemsetSize) {
      generateFrequentItemsets()
      k += 1
    }
    generateAssociationRules()
  }
  def generateItemsetsOfSizeOne(): Unit = {
    val distinctItems = transactions.flatten.distinct
    itemsets = distinctItems.map(List(_))
  }
  def generateFrequentItemsets(): Unit = {
    val candidateItemsets = generateCandidateItemsets()
    frequentItemsets = candidateItemsets.filter(support(_) >= minSupport)
    itemsets = frequentItemsets
  }
  def generateCandidateItemsets(): List[List[String]] = {
    itemsets.flatMap(itemset1 =>
      itemsets.filter(itemset2 => itemset1.last < itemset2.last).map(itemset2 => itemset1 ++ List(itemset2.last))
    ).distinct
  }
  def support(itemset: List[String]): Double = {
    val count = transactions.count(transaction => itemset.forall(transaction.contains))
    count.toDouble / transactions.size
  }
  def confidence(rule: (List[String], List[String])): Double = {
    support(rule._1 ++ rule._2) / support(rule._1)
  }
  def generateAssociationRules(): Unit = {
    frequentItemsets.foreach(itemset => {
      if (itemset.size > 1) {
        val subsets = itemset.toSet.subsets().filter(_.nonEmpty).toList.map(_.toList.sorted)
        subsets.foreach(subset => {
          val complement = itemset.diff(subset)
          val rule = (subset, complement)
          if (confidence(rule) >= minConfidence) {
            associationRules = associationRules :+ rule
          }
        })
      }
    })
  }
  def getFrequentItemsets(): List[List[String]] = frequentItemsets
  def getAssociationRules(): List[(List[String], List[String])] = associationRules
}
```
