Sure, here's a Scala code implementation of the Apriori algorithm that can find frequent itemsets and association rules in your dataset:
```
import scala.collection.mutable.ListBuffer
class Apriori(val transactions: List[List[String]], val minSupport: Double, val minConfidence: Double) {
  val items: List[String] = transactions.flatten.distinct.sorted
  val numTransactions: Int = transactions.length
  val minSupportCount: Int = (minSupport * numTransactions).ceil.toInt
  def run(): Unit = {
    var itemsets: List[List[String]] = items.map(List(_))
    var k: Int = 2
    var frequentItemsets: List[List[String]] = List.empty
    while (itemsets.nonEmpty) {
      val candidates: List[List[String]] = generateCandidates(itemsets)
      val frequentCandidates: List[List[String]] = getFrequentItemsets(candidates)
      frequentItemsets = frequentItemsets ++ frequentCandidates
      itemsets = frequentCandidates.map(_.combinations(k).toList).flatten.distinct
      k += 1
    }
    val rules: List[(List[String], List[String], Double)] = generateRules(frequentItemsets)
    printResults(frequentItemsets, rules)
  }
  def generateCandidates(itemsets: List[List[String]]): List[List[String]] = {
    itemsets.map(itemset1 => itemsets.map(itemset2 => itemset1 ++ itemset2)).flatten
      .filter(candidate => candidate.length == candidate.distinct.length)
      .map(_.sorted).distinct
  }
  def getFrequentItemsets(candidates: List[List[String]]): List[List[String]] = {
    candidates.filter(candidate => countSupport(candidate) >= minSupportCount)
  }
  def countSupport(itemset: List[String]): Int = {
    transactions.count(transaction => itemset.forall(transaction.contains))
  }
  def generateRules(frequentItemsets: List[List[String]]): List[(List[String], List[String], Double)] = {
    frequentItemsets.flatMap(itemset => {
      val subsets: List[List[String]] = itemset.combinations(itemset.length - 1).toList
      subsets.map(subset => {
        val remaining: List[String] = itemset.diff(subset)
        val confidence: Double = countSupport(itemset).toDouble / countSupport(subset).toDouble
        (subset, remaining, confidence)
      })
    }).filter(rule => rule._3 >= minConfidence)
  }
  def printResults(frequentItemsets: List[List[String]], rules: List[(List[String], List[String], Double)]): Unit = {
    println("Frequent itemsets:")
    frequentItemsets.foreach(itemset => println(s"${itemset.mkString("[", ", ", "]")}"))
    println("\nAssociation rules:")
    rules.foreach(rule => println(s"${rule._1.mkString("[", ", ", "]")} => ${rule._2.mkString("[", ", ", "]")} (confidence: ${rule._3})"))
  }
}
object Apriori {
  def main(args: Array[String]): Unit = {
    val transactions: List[List[String]] = List(
      List("bread", "milk", "eggs"),
      List("bread", "milk", "cheese"),
      List("bread", "butter"),
      List("milk", "butter"),
      List("bread", "milk", "butter"),
      List("bread", "milk", "eggs", "cheese"),
      List("eggs", "cheese")
    )
    val minSupport: Double = 0.5
    val minConfidence: Double = 0.8
    val apriori: Apriori = new Apriori(transactions, minSupport, minConfidence)
    apriori.run()
  }
}
```
In this implementation, the `Apriori` class takes in a list of transactions, a minimum support threshold, and a minimum confidence threshold. The `run` method executes the Apriori algorithm and generates frequent itemsets and association rules. The `generateCandidates` method generates candidate itemsets from a list of existing itemsets, the `getFrequentItemsets` method returns the frequent itemsets from a list of candidate itemsets, the `countSupport` method calculates the support count for an itemset, and the `generateRules` method generates association rules from frequent itemsets. The `printResults` method prints the frequent itemsets and association rules to the console.
To use this implementation, you can create an instance of the `Apriori` class with your own dataset and adjust the minimum support and confidence thresholds as desired.

